      "recommended_action": "Investigate CI claims coding, case mix, or external factors in 2018-2019; confirm whether elevated experience reflects an isolated event or requires pricing/assumption adjustment."
    },
    {
      "benefit": "IP",
      "years": [2015, 2024],
      "pattern": "volatility",
      "direction": "dispersion",
      "magnitude": "empirical SD ~0.044 vs Poisson ~0.026 (1.7x)",
      "confidence": 0.7,
      "evidence": [
        "ae_ip_by_year.csv: A/E swings 0.935–1.084 exceed expected sampling noise for claim counts 1000–2000; no sustained trend or level shift"
      ],
      "recommended_action": "Review IP reporting lags, policy mix, or claims handling practices; adjust dispersion assumptions in pricing/valuation to reflect higher process variance."
    }
  ]
}

